import sys
from itertools import combinations

data = sys.stdin.read().split()
pos = 0
n = int(data[pos]); pos += 1
ids = [int(x) for x in data[pos:pos + n]]; pos += n
e = int(data[pos]); pos += 1
edges = []
for _ in range(e):
    edges.append((int(data[pos]), int(data[pos + 1])))
    pos += 2
a = int(data[pos]); b = int(data[pos + 1])

def reaches(blocked):
    adj = {v: [] for v in ids}
    for p, q in edges:
        if q == a and p in blocked:
            continue
        adj[p].append(q)
    seen = {b}
    stack = [b]
    while stack:
        u = stack.pop()
        for v in adj[u]:
            if v not in seen:
                seen.add(v)
                stack.append(v)
    return a in seen

followers = sorted(set(p for p, q in edges if q == a and p != a))
ans = None
for k in range(len(followers) + 1):
    for comb in combinations(followers, k):
        if not reaches(set(comb)):
            ans = list(comb)
            break
    if ans is not None:
        break
print(' '.join(map(str, [len(ans)] + ans)))

